package rs.unicredit.api.gateway.proxy;

import java.net.MalformedURLException;
import java.net.URI;
import java.net.URISyntaxException;

import javax.servlet.http.HttpServletRequest;

import org.apache.http.client.methods.RequestBuilder;
import org.apache.http.client.utils.URIBuilder;
import org.springframework.http.HttpStatus;
import org.springframework.web.bind.annotation.RequestMethod;
import org.springframework.web.client.HttpServerErrorException;

import rs.unicredit.api.gateway.configuration.ApiGatewayProperties;

public class URLRequestTransformer extends ProxyRequestTransformer {

	private ApiGatewayProperties apiGatewayProperties;

	public URLRequestTransformer(ApiGatewayProperties apiGatewayProperties) {
		this.apiGatewayProperties = apiGatewayProperties;
	}

	@Override
	public RequestBuilder transform(HttpServletRequest request) throws URISyntaxException, MalformedURLException {
		String requestURI = request.getRequestURI().replaceAll("/api-gateway", "");
		System.out.println(requestURI);
		URI uri;
		if (request.getQueryString() != null && !request.getQueryString().isEmpty()) {
			uri = new URI(getServiceUrl(requestURI, request) + "?" + request.getQueryString());
		}
		else if (request.getParameterMap() != null && !request.getParameterMap().isEmpty()) {
			URIBuilder uriBuilder = new URIBuilder(getServiceUrl(requestURI, request));
			request.getParameterMap().forEach((key, value) -> uriBuilder.setParameter(key, value[0]));
			uri = uriBuilder.build();
		}
		else {
			uri = new URI(getServiceUrl(requestURI, request));
		}

		RequestBuilder rb = RequestBuilder.create(request.getMethod());
		rb.setUri(uri);
		return rb;
	}

	private String getServiceUrl(String requestURI, HttpServletRequest httpServletRequest)
			throws HttpServerErrorException {

		ApiGatewayProperties.Endpoint endpoint = apiGatewayProperties.getEndpoints().stream()
				.filter(endpointConfig -> requestURI.matches(endpointConfig.getPath())
						&& endpointConfig.getMethod() == RequestMethod.valueOf(httpServletRequest.getMethod()))
				.findFirst()
				.orElseThrow(() -> new HttpServerErrorException(HttpStatus.METHOD_NOT_ALLOWED,
						"Http URI or Method not supported -- URI: " + httpServletRequest.getServletPath() + " Method: "
								+ httpServletRequest.getMethod()));
		return endpoint.getLocation() + requestURI;
	}
}
