			uri = uriBuilder.build();
		}
		else {
			uri = new URI(getServiceUrl(requestURI, request));
		}

		RequestBuilder rb = RequestBuilder.create(request.getMethod());
		rb.setUri(uri);
		return rb;
	}

	private String getServiceUrl(String requestURI, HttpServletRequest httpServletRequest)
			throws HttpServerErrorException {

		ApiGatewayProperties.Endpoint endpoint = apiGatewayProperties.getEndpoints().stream()
				.filter(endpointConfig -> requestURI.matches(endpointConfig.getPath())
						&& endpointConfig.getMethod() == RequestMethod.valueOf(httpServletRequest.getMethod()))
				.findFirst()
				.orElseThrow(() -> new HttpServerErrorException(HttpStatus.METHOD_NOT_ALLOWED,
						"Http URI or Method not supported -- URI: " + httpServletRequest.getServletPath() + " Method: "
								+ httpServletRequest.getMethod()));
		return endpoint.getLocation() + requestURI;
	}
}
