import rs.unicredit.api.db.reader.rtb.soap.AccountBalanceInfo;
import rs.unicredit.api.db.reader.service.ReportingService;
import rs.unicredit.api.model.ServiceResponse;

@RestController
@RequestMapping("/v1/api-db-reader")
@Api(value="accounts-controller", description="Controller exposing operations for obtaining client account data")
public class AccountsController {

	private static final Logger logger = LoggerFactory.getLogger(AccountsController.class);
	
	@Autowired
	ReportingService reportingService;

	@Autowired
	IHUBRtbService ihubService;
		
	
	/**
	 * Method for retrieving Core02 account list using the selection criteria provided in the 
	 * service call.Possible search criteria include client id in Core02.
	 * 
	 * Method call to the database is paginated - with default values if not provided
	 * explicitly. 
	 * 
	 * @param clientId
	 * @param page
	 * @param pageSize
	 * @return
	 */
	@Timed(value = "accounts_http_requests")
	@ApiOperation(value = "Return list of accounts fitting the search criteria", response = List.class)
	@RequestMapping(
			value = "/clients/{clientId}/accounts", 
			method = RequestMethod.GET, 
			produces = MediaType.APPLICATION_JSON_VALUE
			)
	public ResponseEntity<ServiceResponse<List<Account>>> getAccountsBySeachCriteriaPaginated(
			@PathVariable String clientId,
			@RequestParam(value = "page", defaultValue = "1") int page,
			@RequestParam(value = "pageSize", defaultValue = "250") int pageSize) {
		
		logger.debug("Invoking account search by criteria");
		List<Account> accounts = reportingService.getAccountsBySerachCriteria(clientId, null, null, page, pageSize);
		
		if (accounts.size() > 0)	
			return new ResponseEntity<>(
        		new ServiceResponse<>(
        				HttpStatus.OK.value(),
        				"Account search results successfully retrieved",
        				null,
        				accounts)
        		, HttpStatus.OK);
		else 
			return new ResponseEntity<>(
        		new ServiceResponse<>(
        				HttpStatus.NOT_FOUND.value(),
        				"Account search gerenrated no results for provided criteria",
        				null,
        				accounts)
        		, HttpStatus.NOT_FOUND);
	}
	
	
	/**
	 * Method for retrieving Core02 account details using it - combination of operating unit
	 * and account number. 
	 * 
	 * @param operatingunit
	 * @param accountNumber
	 * @return
	 */
	@Timed(value = "accounts_http_requests")
	@ApiOperation(value = "Return list of accounts fitting the search criteria", response = Account.class)
	@RequestMapping(
			value = "/clients/{clientId}/accounts/{accountNumber}", 
			method = RequestMethod.GET, 
			produces = MediaType.APPLICATION_JSON_VALUE
			)
	public ResponseEntity<ServiceResponse<Account>> getClientAccount(
			@PathVariable String clientId,
			@PathVariable String accountNumber) {
		
		logger.debug("Invoking account details search by id");
		List<Account> accounts = reportingService.getAccountsBySerachCriteria(clientId, null, accountNumber, 1, 10);
		
		if (accounts.size() > 0)	
			return new ResponseEntity<>(
        		new ServiceResponse<>(
        				HttpStatus.OK.value(),
        				"Account details successfully retrieved",
        				null,
        				accounts.get(0))
        		, HttpStatus.OK);
		else 
			return new ResponseEntity<>(
        		new ServiceResponse<>(
        				HttpStatus.NOT_FOUND.value(),
        				"Account details not found",
        				"No account details for selected account - " + accountNumber,
        				null)
        		, HttpStatus.NOT_FOUND);
	}
	
	
	/**
	 * Method for retrieving Core02 account details using it - combination of operating unit
	 * and account number. 
	 * 
	 * @param operatingUnit
	 * @param accountNumber
	 * @return
	 */
	@Timed(value = "accounts_http_requests")
	@ApiOperation(value = "Return list of accounts fitting the search criteria", response = Account.class)
	@RequestMapping(
			value = "/accounts/{operatingUnit}/{accountNumber}", 
			method = RequestMethod.GET, 
			produces = MediaType.APPLICATION_JSON_VALUE
			)
	public ResponseEntity<ServiceResponse<Account>> getAccountDetails(
			@PathVariable String operatingUnit,
			@PathVariable String accountNumber) {
		
		logger.debug("Invoking account details search by id");
		List<Account> accounts = reportingService.getAccountsBySerachCriteria(null, operatingUnit, accountNumber, 1, 10);
		
		if (accounts.size() > 0)	
			return new ResponseEntity<>(
        		new ServiceResponse<>(
        				HttpStatus.OK.value(),
        				"Account details successfully retrieved",
        				null,
        				accounts.get(0))
        		, HttpStatus.OK);
		else 
			return new ResponseEntity<>(
        		new ServiceResponse<>(
        				HttpStatus.NOT_FOUND.value(),
        				"Account details not found",
        				"No account details for selected account - " + operatingUnit + "/" + accountNumber,
        				null)
        		, HttpStatus.NOT_FOUND);
	}

	/**
	 * Method for retrieving Core02 account real time balance details using it - combination of operating unit
	 * and account number.
	 *
	 * @param operatingUnit
	 * @param accountNumber
	 * @return
	 */
	@Timed(value = "accounts_http_requests")
	@ApiOperation(value = "Return real time balance details of accounts fitting the search criteria", response = Account.class)
	@RequestMapping(
			value = "/accounts/rtb/{operatingUnit}/{accountNumber}",
			method = RequestMethod.GET,
			produces = MediaType.APPLICATION_JSON_VALUE
	)
