package rs.unicredit.api.db.reader.configuration;

import javax.persistence.EntityManagerFactory;
import javax.sql.DataSource;

import org.springframework.beans.factory.annotation.Qualifier;
import org.springframework.boot.context.properties.ConfigurationProperties;
import org.springframework.boot.jdbc.DataSourceBuilder;
import org.springframework.boot.orm.jpa.EntityManagerFactoryBuilder;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.context.annotation.Primary;
import org.springframework.data.jpa.repository.config.EnableJpaRepositories;
import org.springframework.orm.jpa.JpaTransactionManager;
import org.springframework.orm.jpa.LocalContainerEntityManagerFactoryBean;
import org.springframework.transaction.PlatformTransactionManager;
import org.springframework.transaction.annotation.EnableTransactionManagement;

/**
 * Reporting data source configuration class - allowing a data source and transaction factory
 * to be initiated and used.
 * 
 * @author Vladimir Rupar
 *
 */
@Configuration
@EnableTransactionManagement
@EnableJpaRepositories (
		entityManagerFactoryRef = "reportingEntityManagerFactory",
		basePackages = { "rs.unicredit.api.db.reader.repository" }
		)
public class ReportingConfiguration { 

	@Primary
	@Bean(name = "reportingDataSource")
	@ConfigurationProperties(prefix = "datasource.reporting")
	public DataSource dataSource() {
		return DataSourceBuilder.create().build();
	}
	
	@Primary
	@Bean(name = "reportingEntityManagerFactory")
	public LocalContainerEntityManagerFactoryBean entityManagerFactory(
	    EntityManagerFactoryBuilder builder,
	    @Qualifier("reportingDataSource") DataSource dataSource
	  ) {
	    return builder
	      .dataSource(dataSource)
	      .packages("rs.unicredit.api.db.reader.model")
	      .persistenceUnit("reporting")
	      .build();
	  }
	    
	  @Primary
	  @Bean(name = "reportingTransactionManager")
	  public PlatformTransactionManager transactionManager(
	    @Qualifier("reportingEntityManagerFactory") EntityManagerFactory 
	    entityManagerFactory
	  ) {
	    return new JpaTransactionManager(entityManagerFactory);
	  }
	
}
